    if b == 0 {
        Err("division by zero".to_string())
    } else {
        Ok(a / b)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_safe_divide_normal() {
        assert_eq!(safe_divide(10, 2), Ok(5));
    }

    #[test]
    fn test_safe_divide_by_zero() {
        assert_eq!(
            safe_divide(10, 0),
            Err("division by zero".to_string())
        );
    }

    #[test]
    fn test_safe_divide_negative_dividend() {
        assert_eq!(safe_divide(-10, 2), Ok(-5));
    }

    #[test]
    fn test_safe_divide_zero_dividend() {
        assert_eq!(safe_divide(0, 2), Ok(0));
    }
}

